cePosition": "right", "targetPosition": "left", "type": "custom", "width": 242}, {"data": {"context": {"enabled": false, "variable_selector": []}, "model": {"completion_params": {"temperature": 0.7, "reasoning_effort": "high"}, "mode": "chat", "name": "deepseek-flash", "provider": "langgenius/deepseek/deepseek"}, "prompt_template": [{"id": "961f94cd-f0ed-4ca0-ab49-7d797d67f6a6", "role": "system", "text": ""}, {"id": "1562435c-7ca5-40fb-8e7d-fa8b2c5496e6", "role": "user", "text": "你是 jwave 声学仿真代码生成器。根据用户需求生成可直接运行的 jwave Python 代码。\n\n【正确 API（硬约束）】jwave 所有类和函数都从顶层导入，禁止使用不存在的子模块：\nimport jwave as jw\nimport jax.numpy as jnp\nfrom jwave import Domain, Medium, TimeAxis, Sources, Sensors, simulate_wave_propagation\n\n【代码结构】严格按以下顺序生成：\n\n# 1. 计算域（Nx,Ny 为网格点数，dx,dy 为网格间距，由需求推导）\ndomain = Domain((Nx, Ny), (dx, dy))\n\n# 2. 介质\nmedium = Medium(domain, sound_speed=..., density=..., pml_size=20)\n\n# 3. 时间轴\ntime_axis = TimeAxis.from_medium(medium, cfl=0.3, t_end=...)\n\n# 4. 点源（Sources 必须用 4 个位置参数，禁止关键字参数）\ndt = time_axis.dt\nt = time_axis.to_array()\npositions = (jnp.array([cx]), jnp.array([cy]))   # 坐标必须是整数 int32\nsignal = jnp.sin(2 * jnp.pi * freq * t)\nsignals = jnp.expand_dims(signal, 0)             # 必须是 2D，shape=(1, Nt)\nsources = Sources(positions, signals, dt, domain)\n\n# 5. 仿真\nresult = simulate_wave_propagation(medium, time_axis, sources=sources)\n\n# 6. 场数据输出（必须！输出全时最大绝对压力场 JSON 供分析，大网格自动降采样防超限）\nimport json as __json\nimport jax.numpy as __jnp\n__field = __jnp.max(__jnp.abs(result.params), axis=0)[..., 0]\n__maxp = float(__jnp.max(__field))\n__step = 1\nwhile __field.size / (__step * __step) > 40000:\n    __step += 1\n__field_out = __field[::__step, ::__step] if __step > 1 else __field\nprint(\"__ACOU_FIELD_START__\")\nprint(__json.dumps({\"shape\": list(__field_out.shape), \"kind\": \"field\", \"downsample\": __step, \"max_pressure\": __maxp, \"data\": __field_out.tolist()}))\nprint(\"__ACOU_FIELD_END__\")\nprint(f\"最大压力: {__maxp:.6f}\")\n\n【参数映射】从用户需求提取：sound_speed→介质声速、density→密度、source_frequency→freq、网格大小→(dx,dy)与(Nx,Ny)、仿真时长→t_end。如果用户没给某参数，用合理默认值（声速 1500、密度 1000、freq 1e6、pml_size 20）。\n\n【禁止事项】\n- 禁止 from jwave.sources import ...（jwave 没有 sources 模块）\n- 禁止 PointSource 类（不存在）\n- 禁止 Sources 用关键字参数\n- 禁止 positions 用浮点数（必须整数）\n- 禁止 signals 用 list 或 tuple（必须 2D jnp array）\n\n用户需求：\n{{#1783990934733.query#}}\n\n输出要求：仅输出完整 Python 代码，不要 markdown 代码块，不要解释，不要 <think> 标签。"}], "selected": true, "structured_output": {"schema": {"additionalProperties": false, "properties": {"code": {"description": "将代码注入到这里，解释器会自动运行", "type": "string"}}, "required": [], "type": "object"}}, "structured_output_enabled": true, "title": "代码生成", "type": "llm", "vision": {"enabled": false}}, "height": 89, "id": "1783991079665", "position": {"x": 1197.0337969229192, "y": 506.64150382829416}, "positionAbsolute": {"x": 1197.0337969229192, "y": 506.64150382829416}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 242}, {"data": {"outputs": [{"value_selector": ["1783994256713", "code_final"], "value_type": "string", "variable": "text"}], "selected": false, "title": "输出", "type": "end"}, "height": 89, "id": "1783992518452", "position": {"x": 3825.4020280085774, "y": 157.900615026916}, "positionAbsolute": {"x": 3825.4020280085774, "y": 157.900615026916}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 242}, {"data": {"break_conditions": [], "error_handle_mode": "terminated", "height": 501, "logical_operator": "and", "loop_count": 10, "loop_variables": [{"id": "c84e0dcc-ae90-4bc9-a98f-2f58f3eba5bd", "label": "code_final", "value": ["1783991079665", "text"], "value_type": "variable", "var_type": "string"}], "selected": false, "start_node_id": "1783994256713start", "title": "循环", "type": "loop", "width": 1623}, "height": 501, "id": "1783994256713", "position": {"x": 1723.0405284713713, "y": 432.6043210562211}, "positionAbsolute": {"x": 1723.0405284713713, "y": 432.