nking_model": {"model": "qwen3-rerank", "provider": "langgenius/tongyi/tongyi"}, "reranking_enable": true}, "query_attachment_selector": [], "query_variable_selector": ["1783990934733", "query"], "retrieval_mode": "multiple", "selected": false, "title": "知识检索", "type": "knowledge-retrieval"}, "height": 89, "id": "1783990977543", "position": {"x": 609, "y": 552}, "positionAbsolute": {"x": 609, "y": 552}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 242}, {"data": {"selected": false, "template": "{% for item in arg1 %}\r\n{{ item.content }}\r\n{% endfor %}\r\n", "title": "模板转换", "type": "template-transform", "variables": [{"value_selector": ["1783990977543", "result"], "value_type": "array[object]", "variable": "arg1"}]}, "height": 51, "id": "1783990989034", "position": {"x": 910, "y": 552}, "positionAbsolute": {"x": 910, "y": 552}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 242}, {"data": {"context": {"enabled": true, "variable_selector": ["1783990989034", "output"]}, "model": {"completion_params": {"temperature": 0.7}, "mode": "chat", "name": "deepseek-flash", "provider": "langgenius/deepseek/deepseek"}, "prompt_template": [{"id": "34a28900-fed5-4647-a9ac-8f3e72ac49c7", "role": "system", "text": ""}, {"id": "2207227c-adc1-4894-ba3e-34c701909807", "role": "user", "text": "你是一个 jwave 声学仿真参数提取器。根据用户需求和知识库内容，提取 JSON 参数。\n \n用户需求：{{#1783990934733.query#}}\n知识库参考：{{#1783990989034.output#}}\n \n请严格按照结构化输出中定义的 JSON Schema 输出，只输出 JSON，不要有其他解释。"}], "selected": false, "title": "参数提取", "type": "llm", "vision": {"enabled": false}}, "height": 87, "id": "1783991048409", "position": {"x": 1167.4588864619998, "y": 282}, "positionAbsolute": {"x": 1167.4588864619998, "y": 282}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 242}, {"data": {"context": {"enabled": false, "variable_selector": []}, "model": {"completion_params": {"temperature": 0.7}, "mode": "chat", "name": "deepseek-flash", "provider": "langgenius/deepseek/deepseek"}, "prompt_template": [{"id": "961f94cd-f0ed-4ca0-ab49-7d797d67f6a6", "role": "system", "text": ""}, {"id": "1562435c-7ca5-40fb-8e7d-fa8b2c5496e6", "role": "user", "text": "你是 jwave 声学仿真代码生成器。根据用户需求生成可直接运行的 jwave Python 代码。\n\n【正确 API（硬约束）】jwave 所有类和函数都从顶层导入，禁止使用不存在的子模块：\nimport jwave as jw\nimport jax.numpy as jnp\nfrom jwave import Domain, Medium, TimeAxis, Sources, Sensors, simulate_wave_propagation\n\n【代码结构】严格按以下顺序生成：\n\n# 1. 计算域（Nx,Ny 为网格点数，dx,dy 为网格间距，由需求推导）\ndomain = Domain((Nx, Ny), (dx, dy))\n\n# 2. 介质\nmedium = Medium(domain, sound_speed=..., density=..., pml_size=20)\n\n# 3. 时间轴\ntime_axis = TimeAxis.from_medium(medium, cfl=0.3, t_end=...)\n\n# 4. 点源（Sources 必须用 4 个位置参数，禁止关键字参数）\ndt = time_axis.dt\nt = time_axis.to_array()\npositions = (jnp.array([cx]), jnp.array([cy]))   # 坐标必须是整数 int32\nsignal = jnp.sin(2 * jnp.pi * freq * t)\nsignals = jnp.expand_dims(signal, 0)             # 必须是 2D，shape=(1, Nt)\nsources = Sources(positions, signals, dt, domain)\n\n# 5. 仿真\nresult = simulate_wave_propagation(medium, time_axis, sources=sources)\n\n# 6. 可视化\njw.show_field(result[-1], ''Final pressure field'')\n\n【参数映射】从用户需求提取：sound_speed→介质声速、density→密度、source_frequency→freq、网格大小→(dx,dy)与(Nx,Ny)、仿真时长→t_end。如果用户没给某参数，用合理默认值（声速 1500、密度 1000、freq 1e6、pml_size 20）。\n\n【禁止事项】\n- 禁止 from jwave.sources import ...（jwave 没有 sources 模块）\n- 禁止 PointSource 类（不存在）\n- 禁止 Sources 用关键字参数\n- 禁止 positions 用浮点数（必须整数）\n- 禁止 signals 用 list 或 tuple（必须 2D jnp array）\n\n用户需求：\n{{#1783990934733.query#}}\n\n输出要求：仅输出完整 Python 代码，不要 markdown 代码块，不要解释，不要 <think> 标签。"}], "selected": false, "structured_output": {"schema": {"additionalProperties": false, "properties": {"code": {"description": "将代码注入到这里，解释器会自动运行", "type": "string"}}, "required": [], "type": "object"}}, "structured_output_enabled": true, "title": "代码生成", "type": "llm", "vision": {"enabled": false}, "reasoning_format": "separated"}, 